import{_ as n,a0 as a,w as i,s as d,I as l,x as p,a1 as o,A as r,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"LFTP : 一个功能强大的命令行FTP程序 | LCTT x X-CMD","titleTemplate":false,"description":"LFTP : 一个功能强大的命令行FTP程序 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFTP : 一个功能强大的命令行FTP程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFTP : 一个功能强大的命令行FTP程序 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150306 How to Setup lftp--A Simple Command line FTP Program","title":"LFTP : 一个功能强大的命令行FTP程序","tag":"201505","desc":""},"relativePath":"201505/20150306 How to Setup lftp--A Simple Command line FTP Program.md","filePath":"[post].md"}'),g={name:"201505/20150306 How to Setup lftp--A Simple Command line FTP Program.md"};function u(m,t,f,c,h,x){const e=a("Link");return i(),d("div",null,[t[16]||(t[16]=l("h1",{id:"lftp-一个功能强大的命令行ftp程序",tabindex:"-1"},[p("LFTP : 一个功能强大的命令行FTP程序 "),l("a",{class:"header-anchor",href:"#lftp-一个功能强大的命令行ftp程序","aria-label":"Permalink to “LFTP : 一个功能强大的命令行FTP程序”"},"​")],-1)),l("p",null,[t[1]||(t[1]=p("大家好，这篇文章是介绍Lftp以及如何在Linux操作系统下安装的。",-1)),o(e,{href:"http://lftp.yar.ru/"},{default:r(()=>[...t[0]||(t[0]=[p("Lftp",-1)])]),_:1}),t[2]||(t[2]=p("是一个基于命令行的文件传输软件（也被称为FTP客户端），由Alexander Lukyanov开发并以GNU GPL协议许可发行。除了FTP协议外，它还支持FTPS，HTTP，HTTPS，HFTP，FISH，以及SFTP等协议。这个程序还支持FXP，允许数据绕过客户端直接在两个FTP服务器之间传输。",-1))]),t[17]||(t[17]=s(`<p>它有很多很棒的高级功能，比如递归镜像整个目录树以及断点续传下载。传输任务可以安排在稍后的时间段计划执行，可以限制带宽，可以创建传输列表，还支持类似Unix shell的任务控制。客户端还可以在交互式或自动脚本里使用。</p><h3 id="安装lftp" tabindex="-1">安装Lftp <a class="header-anchor" href="#安装lftp" aria-label="Permalink to “安装Lftp”">​</a></h3><p>在运行lftp之前，我们需要确定它已经正确安装在我们的Linux发行版中了。下面是在常见Linux发行版中安装lftp的一些命令。</p><p><strong>Ubuntu 14.04 LTS</strong></p><p>在Ubuntu 14.04 LTS以及它的衍生版中，我们可以通过apt管理程序安装lftp。要安装它，我们需要使用sudo权限在shell或终端里运行下面的命令。</p><pre><code>$ sudo apt-get install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ubuntu-install-lftp.png" alt="ubuntu install lftp"></p><p><strong>CentOS/Fedora/RHEL</strong></p><p>因为在Fedora，CentOS和RHEL的软件仓库里也能找到lftp，我们可以用<strong>yum</strong>管理程序来安装它。</p><pre><code>$ sudo yum install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/fedora-lftp.png" alt="fedora lftp"></p><p><strong>Arch Linux</strong></p><p>在Arch Linux安装包仓库里也有，我们可以简单地使用pacman来安装它。</p><pre><code>$ sudo pacman -S lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/archlinux-install-lftp.png" alt="archlinux install lftp"></p><p><strong>OpenSuse</strong></p><p>OpenSuse系统里的包管理软件Zypper可以用来安装lftp。下面是在OpenSuse机器上用来安装的命令。</p><pre><code>$ sudo zypper install lftp
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp_install.png" alt="opensuse lftp install"></p><h3 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to “登录”">​</a></h3><p>要登录到ftp服务器或sftp服务器，我们首先需要知道所要求的认证信息，比如用户名，密码，端口。</p><p>之后，我们可以通过lftp来登录。</p><pre><code>$ lftp ftp://linoxide@localhost
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp-login.png" alt="ftp login"></p><p>如果需要指定登录端口，我们可以按下面的方式加上去。</p><pre><code>$ lftp ftp://linoxide@localhost:21
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/lftp-login-port.png" alt="ftp login with ports"></p><h3 id="导航" tabindex="-1">导航 <a class="header-anchor" href="#导航" aria-label="Permalink to “导航”">​</a></h3><p>我们可以用<strong>ls</strong>命令来列出文件和目录，用<strong>cd</strong>命令进入到目录。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ls-cd-lftp.png" alt="ls and cd"></p><h3 id="上传和下载文件" tabindex="-1">上传和下载文件 <a class="header-anchor" href="#上传和下载文件" aria-label="Permalink to “上传和下载文件”">​</a></h3><p>我们可以用<strong>pget</strong>命令来从远端服务器下载文件。</p><pre><code>&gt; pget linspeed.svg
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/pget-lftp.png" alt="pget lftp"></p><p>我们可以用<strong>put</strong>命令来上传文件到远端服务器。</p><pre><code>&gt; put linoxide.tar
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/put-upload.png" alt="upload with put"></p><p>要恢复之前只下载了一部分的文件/目录，我们可以用-c开关：</p><pre><code>&gt; mirror -c Directory

&gt;pget -c linoxide.tar

&gt; put -c upload.tar
</code></pre><h3 id="使用镜像命令" tabindex="-1">使用镜像命令 <a class="header-anchor" href="#使用镜像命令" aria-label="Permalink to “使用镜像命令”">​</a></h3><p>我们可以用mirror命令来下载所指定的整个目录。</p><pre><code>&gt; mirror remote local
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/mirror.png" alt="download with mirror"></p><p>还可以做反向镜像(mirror -R)，可以用来上传或更新本地目录树到服务器上。</p><pre><code>&gt; mirror -R local remote
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/mirror-reverse.png" alt="upload or update with mirror reverse"></p><p>要恢复之前下载了一部分的文件/目录，我们可以用-c开关：</p><pre><code>&gt; mirror -c Directory
</code></pre><h3 id="下载队列" tabindex="-1">下载队列 <a class="header-anchor" href="#下载队列" aria-label="Permalink to “下载队列”">​</a></h3><p>我们可以在lftp里使用queue的选项，这样我们可以像基于GUI的客户端那样挨个下载队列里选择的文件。下面举个例子。</p><p>为了避免队列自动开始传输，我们可以这样做：</p><pre><code>&gt; queue stop
</code></pre><p>现在，我们添加任务到队列。</p><pre><code>&gt; queue mirror &quot;directory&quot;

&gt; queue pget &quot;file.tar&quot;
</code></pre><p>在建立好队列后，我们再运行queue start命令。</p><pre><code>&gt; queue start
</code></pre><p>可以运行下面的命令移除整个队列。</p><pre><code>&gt; queue -d
</code></pre><h3 id="分块下载" tabindex="-1">分块下载 <a class="header-anchor" href="#分块下载" aria-label="Permalink to “分块下载”">​</a></h3><p>下面是一个把一个文件分成3块来下载的例子，你可以根据自己的需要调整。</p><p>使用pget命令分块功能的方式是<strong>pget -n 3 file.tar</strong>，里面的3是分块的数目。</p><pre><code>&gt; pget -n 3 file.tar
</code></pre><p>使用mirror命令分块功能的方式是<strong>mirror --use-pget-n=3 directory</strong>，里面的3是分块的数目。</p><pre><code>&gt; mirror --use-pget-n=3 linxoxide
</code></pre><p>我们可以用jobs -v命令来查看每个独立分块的下载速度以及整体速度。</p><h3 id="停止-继续或删除一次传输任务" tabindex="-1">停止，继续或删除一次传输任务 <a class="header-anchor" href="#停止-继续或删除一次传输任务" aria-label="Permalink to “停止，继续或删除一次传输任务”">​</a></h3><p>要取消传输我们可以按下Ctrl+C。而要恢复下载我们可以像下面那样使用-c (--continue)开关。</p><pre><code>&gt; mirror -c directory
</code></pre><p>要删除一次正在正在传输的任务我们可以用<strong>kill</strong>命令，而要删除所有任务我们可以使用下面那样的<strong>kill all</strong>命令。</p><pre><code>&gt; kill

&gt; kill all
</code></pre><h3 id="退出" tabindex="-1">退出 <a class="header-anchor" href="#退出" aria-label="Permalink to “退出”">​</a></h3><p>要从lftp退出，我们需要在终端或lftp交互接口中运行exit命令。</p><pre><code>&gt; exit
</code></pre><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>哇！我们已经成功地安装了lftp并学会了它的一些基础的主要使用方式。lftp是一个非常棒的命令行ftp客户端，它支持许多额外的功能以及很酷的特性。它比其他普通ftp客户端多了很多东西。好吧，你要是有任何问题，建议，反馈，请在下面的评论区里留言。谢谢！享用lftp吧 😃</p><hr>`,76)),l("p",null,[t[4]||(t[4]=p("via: ",-1)),o(e,{href:"http://linoxide.com/linux-how-to/setup-lftp-command-line-ftp/"},{default:r(()=>[...t[3]||(t[3]=[p("http://linoxide.com/linux-how-to/setup-lftp-command-line-ftp/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=p("作者：",-1)),o(e,{href:"http://linoxide.com/author/arunp/"},{default:r(()=>[...t[5]||(t[5]=[p("Arun Pyasi",-1)])]),_:1}),t[9]||(t[9]=p(" 译者：",-1)),o(e,{href:"https://github.com/zpl1025"},{default:r(()=>[...t[6]||(t[6]=[p("zpl1025",-1)])]),_:1}),t[10]||(t[10]=p(" 校对：",-1)),o(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[p("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=p("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[p("LCTT",-1)])]),_:1}),t[14]||(t[14]=p(" 原创翻译，",-1)),o(e,{href:"http://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[p("Linux中国",-1)])]),_:1}),t[15]||(t[15]=p(" 荣誉推出",-1))])])}const L=n(g,[["render",u]]);export{b as __pageData,L as default};
